var o=[{title:`Co zalicza się do HIIT`,text:`HIIT wymaga pracy, która jest ciężka dla Twojej obecnej sprawności, zwykle po której następuje łatwiejszy interwał pozwalający na kolejny dobry wysiłek. Ciężki oddech jest oczekiwany, ale utrata kontroli nad techniką nie. Pośpieszne obwody nie dają automatycznie takiego samego efektu treningowego jak ustrukturyzowane tlenowe interwały o wysokiej intensywności.`},{title:`Czym jest Tabata`,text:`Klasyczny format Tabata to osiem rund po 20 sekund ciężkiej pracy i 10 sekund odpoczynku, w sumie cztery minuty. Oryginalne badanie używało bardzo intensywnych wysiłków na rowerze, więc swobodny obwód 20/10 lepiej nazwać „w stylu Tabata”, chyba że wysiłek jest podobny. Krótki protokół nadal wymaga rozgrzewki wcześniej i regeneracji potem.`},{title:`Kto powinien zacząć prościej`,text:`Jeśli wracasz po przerwie w aktywności lub uczysz się nowych ruchów, kilka tygodni wygodnej pracy tlenowej na początek może posłużyć Ci lepiej. Jeśli masz schorzenie, na które może to wpłynąć, zapytaj lekarza przed rozpoczęciem. Burpees i skoki nie są potrzebne, by kardio było intensywne, a rower stacjonarny może być bezpieczniejszy i łatwiejszy do kontrolowania.`},{title:`Ogranicz ciężką pracę`,text:`Zacznij od krótkich interwałów, które ukończysz z dobrą techniką, i zostaw dość łatwych dni między ciężkimi treningami. Podnoszenie jednocześnie częstotliwości, intensywności i liczby rund może przynieść zmęczenie bez dodatkowej korzyści. HIIT to jedna z opcji obok stałej aktywności, treningu siłowego i codziennego chodzenia, a sprawność możesz zdobyć bez niego.`}];var a=[{label:`ACE: projektowanie interwałów o wysokiej intensywności`,url:`https://www.acefitness.org/continuing-education/certified/may-2021/7844/how-to-use-the-ace-ift-model-to-design-effective-hiit-workouts/`},{label:`ACE: oryginalny format interwałów Tabata`,url:`https://www.acefitness.org/continuing-education/prosource/hiit-special-issue/3743/is-tabata-all-it-s-cracked-up-to-be/`},{label:`CDC: zalecenia dotyczące aktywności fizycznej dorosłych`,url:`https://www.cdc.gov/physical-activity-basics/guidelines/adults.html`}];var t={sections:o,sources:a};export{t as default,o as sections,a as sources};